`timescale 1ns/1ps
// Self-checking testbench - generated by scripts/make_experiments.py
// One clock = one model step. Writes tsodyks_markram.csv in the simulator's working directory.
module tb;
    reg clk = 0, rst = 1, en = 1;
    always #5 clk = ~clk;
    integer t, f, errors = 0;
    task check(input [8*24-1:0] what, input integer got, input integer exp);
        begin
            if (exp >= 0 && got !== exp) begin errors = errors + 1; $display("  FAIL %0s: got %0d, expected %0d", what, got, exp); end
            else $display("  ok   %0s = %0d", what, got);
            $display("RESULT %0s=%0d", what, got);
        end
    endtask
    reg pre;
    wire signed [31:0] xd, ud, id, xf, uf, i_f;
    tm_synapse #(.U(32768), .TAU_REC(7), .TAU_FAC(2)) dep (.clk(clk), .rst(rst), .en(en), .pre_spike(pre), .x(xd), .u(ud), .i_syn(id));
    tm_synapse #(.U(6554),  .TAU_REC(3), .TAU_FAC(7)) fac (.clk(clk), .rst(rst), .en(en), .pre_spike(pre), .x(xf), .u(uf), .i_syn(i_f));
    integer pk_d = 0, pk_f = 0, first_d = -1, last_d = 0, first_f = -1, last_f = 0, since = 99;
    initial begin
        f = $fopen("tsodyks_markram.csv", "w"); $fdisplay(f, "t,pre,x_dep,u_dep,i_dep,x_fac,u_fac,i_fac");
        pre = 0; repeat (2) @(posedge clk); #1 rst = 0;
        for (t = 0; t < 400; t = t + 1) begin
            pre = (t == 10) || (t >= 60 && t <= 200 && (t - 60) % 20 == 0) || (t == 330);
            @(posedge clk); #1;
            if (pre) begin since = 0; pk_d = 0; pk_f = 0; end else since = since + 1;
            if (id > pk_d) pk_d = id; if (i_f > pk_f) pk_f = i_f;
            if (since == 4 && t > 55 && t < 210) begin if (first_d < 0) begin first_d = pk_d; first_f = pk_f; end last_d = pk_d; last_f = pk_f; end
            $fdisplay(f, "%0d,%0d,%0d,%0d,%0d,%0d,%0d,%0d", t, pre, xd, ud, id, xf, uf, i_f);
        end
        check("dep_first_peak_Q8", first_d, 1521);
        check("dep_last_peak_Q8", last_d, 612);
        check("fac_first_peak_Q8", first_f, 1007);
        check("fac_last_peak_Q8", last_f, 1919);
        if (errors == 0) $display("*** PASS ***"); else $display("*** FAIL: %0d check(s) ***", errors);
        $fclose(f); $finish;
    end
endmodule
